package com.bank.ingest;

import java.math.BigDecimal;

// Each parsed transaction carries a status word that repeats across millions
// of transactions: "SETTLED", "PENDING", "FAILED".
class Transaction {
    private final String txnId;
    private final String status;   // highly repeated text
    private final BigDecimal amount;

    Transaction(String txnId, String status, BigDecimal amount) {
        this.txnId = txnId;
        this.status = status;
        this.amount = amount;
    }

    String getStatus() { return status; }
    String getTxnId() { return txnId; }
}
