package com.bank.ingest;

// Canonicalizes status strings so equal statuses become the SAME object.
// This is application-level interning (we control it), distinct from GC dedup.
class StatusInterner {

    // Returns the single canonical instance for this status text.
    // "SETTLED".intern() always returns the pooled literal instance.
    String canonical(String raw) {
        return raw == null ? null : raw.intern();
    }
}
