package com.bank.ingest;

// Routes a transaction based on its status.
class StatusRouter {

    // Fast path: when statuses are interned, == is a single pointer compare.
    boolean isSettled(String status, String settledCanonical) {
        return status == settledCanonical; // valid ONLY because both are interned
    }

    // Safe path: works regardless of interning.
    boolean isSettledSafe(String status) {
        return "SETTLED".equals(status);
    }
}
