package com.bank.ingest;

import java.math.BigDecimal;
import java.util.logging.*;

public class StringDedupDemo {
    private static final Logger log = Logger.getLogger(StringDedupDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        StatusInterner interner = new StatusInterner();
        StatusRouter router = new StatusRouter();

        // Simulate parsing: each 'new String(...)' makes a DISTINCT object
        // holding the identical text "SETTLED" — the duplicate problem.
        Transaction t1 = new Transaction("TXN-1", new String("SETTLED"), new BigDecimal("50000"));
        Transaction t2 = new Transaction("TXN-2", new String("SETTLED"), new BigDecimal("12000"));

        // Without interning: equal content but DIFFERENT objects.
        boolean sameObjectRaw = (t1.getStatus() == t2.getStatus());
        log.info(() -> "Raw statuses == ? " + sameObjectRaw + " (distinct objects, duplicate arrays)");

        // With interning: collapse to the SAME canonical object.
        String c1 = interner.canonical(t1.getStatus());
        String c2 = interner.canonical(t2.getStatus());
        boolean sameObjectInterned = (c1 == c2);
        log.info(() -> "Interned statuses == ? " + sameObjectInterned + " (one canonical object)");

        // Fast routing using the canonical settled literal.
        String settled = "SETTLED"; // literal is already interned
        boolean routedFast = router.isSettled(c1, settled);
        log.info(() -> "Fast == routing says settled? " + routedFast);

        // Safe routing still works even on the raw, non-interned string.
        boolean routedSafe = router.isSettledSafe(t2.getStatus());
        log.info(() -> "Safe equals routing says settled? " + routedSafe);

        log.warning(() -> "For the BROAD heap win across millions of messages, run with "
                + "-XX:+UseStringDeduplication on G1 — it shares arrays with ZERO code change.");
    }
}

